use crate::aap::caps::kb_read;

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let q = query.query;

        // The contract guarantees len(question) <= 512; clamp defensively
        // (by chars, which also bounds bytes-agnostic length checks).
        let question: String = if q.question.chars().count() > 512 {
            q.question.chars().take(512).collect()
        } else {
            q.question
        };

        let knowledge = kb_read::lookup(&question);

        ConversationContext {
            intent: q.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
